import java.util.Scanner;

class Cat {
    String name;
    int fish;

    Cat() {
        this("{def}", 0);
    }

    Cat(String name, int fish) {
        this.name = name;
        this.fish = fish;
    }

    void report() {
        System.out.println(this.name + " 有 " + this.fish + " 条小鱼干喵");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String who = sc.next();
        int n = sc.nextInt();

        Cat c1 = new Cat(who, n);
        Cat c2 = new Cat();
        c1.report();
        c2.report();
    }
}
